import{_ as t,o as a,c as o,j as n}from"./chunks/framework.BdHuibk5.js";const m=JSON.parse('{"title":"Changing to a new environment","description":"买了硬盘，清理了四年积累下来的东西，也在新公司度过了刚满半年的日子。新的环境、新的同事、新的节奏，也许本身就是一种新的开始。","frontmatter":{"title":"Changing to a new environment","date":"2012-08-05 00:30","category":"diary","tags":["工作","生活"],"slug":"changing-to-a-new-environment","layout":"blog-post","description":"买了硬盘，清理了四年积累下来的东西，也在新公司度过了刚满半年的日子。新的环境、新的同事、新的节奏，也许本身就是一种新的开始。"},"headers":[],"relativePath":"blog/changing-to-a-new-environment.md","filePath":"blog/posts/diary/changing-to-a-new-environment.md","lastUpdated":1789447662000}'),i={name:"blog/changing-to-a-new-environment.md"};function r(l,e,g,s,p,c){return a(),o("div",null,[...e[0]||(e[0]=[n("p",null,"买了硬盘，把四年积累下来的东西全都清理了一遍。",-1),n("p",null,"给自己笔记本加了一倍的内存，然后还给他好好地洗了一个澡，也算对得起跟了我这么多年的他，估计他才是跟我最久，也是最亲近的朋友了，呵呵，其实我对他还是挺好的。",-1),n("p",null,"来到新的公司，算上这周末，刚好满半年，这短短半年时间里，结识了很多人，自己也慢慢地在成长。新的同事，新的办公环境，新的一切，我觉得过得也是很充实和快乐的。跟一群年纪差不多的同事们在一起，大家也玩得开，也能玩到一块去。在蔡蔡的带领下，酒量大增！自己在技术上虽然进步不大，但毕竟还是有一定的经验积累。住在公司里，让我又回到了曾经的大学，一个宿舍，四个人。大家在一起很开心。但不知道，这到底是好是坏，反正对我影响挺大的。不知道，这样还能继续多久？",-1),n("p",null,"前两天，一位可爱可敬的同事离职了（哈哈），可能离职也许是他的一个转折点，一个新的起点，这是一件好事。这也是再正常不过的事，年轻，是可以这样的！也许，明天，后天，我也步你后路了。哈哈，换个环境，未尝不是件好的事情。但，不管我什么时候走，只要我还在一天，上班做事，必须得要有激情，要有干劲！",-1),n("p",null,"去年这个时候也蓄了一个月的须，今年也一样，从 7 月 5 号到今天，刚好一个月，拍照留念了下，差不多也该修理了。但，我想我每年都会坚持这么一个月。",-1),n("p",null,"Changing to a new environment，probably a good thing！",-1)])])}const u=t(i,[["render",r]]);export{m as __pageData,u as default};
